text.main.ts:
// project start
scene.setBackgroundImage(assets.image`backgroundImage`)
tiles.setCurrentTilemap(tilemap`level`)

let mySprite = sprites.create(assets.image`spriteForward`, SpriteKind.Player)
tiles.placeOnTile(mySprite, tiles.getTileLocation(0, 12))
scene.cameraFollowSprite(mySprite)
controller.moveSprite(mySprite, 100, 0)
mySprite.ay = 500

// project events
controller.A.onEvent(ControllerButtonEvent.Pressed, function () {
    animation.stopAnimation(animation.AnimationTypes.All, mySprite)
    if (mySprite.isHittingTile(CollisionDirection.Bottom)) {
        mySprite.vy = -150
    }
})

scene.onOverlapTile(SpriteKind.Player, assets.tile`ladderTile`, function (sprite, location) {
    if (mySprite.tileKindAt(TileDirection.Center, assets.tile`ladderTile`)) {
        controller.moveSprite(mySprite, 100, 100)
        mySprite.ay = 0
    } else {
        controller.moveSprite(mySprite, 100, 0)
        mySprite.ay = 500
    }
})

controller.up.onEvent(ControllerButtonEvent.Pressed, function () {
    animation.runImageAnimation(mySprite, assets.animation`climbAnim`, 200, true)
})

controller.down.onEvent(ControllerButtonEvent.Pressed, function () {
    animation.runImageAnimation(mySprite, assets.animation`climbAnim`, 200, true)
})

controller.left.onEvent(ControllerButtonEvent.Pressed, function () {
    animation.runImageAnimation(mySprite, assets.animation`walkLeftAnim`, 200, true)
})

controller.right.onEvent(ControllerButtonEvent.Pressed, function () {
    animation.runImageAnimation(mySprite, assets.animation`walkRightAnim`, 200, true)
})

controller.anyButton.onEvent(ControllerButtonEvent.Released, function () {
    animation.stopAnimation(animation.AnimationTypes.ImageAnimation, mySprite)
})

